example.point:
ALGORITHME Inverse ;
VAR nombre : Réel ;
DÉBUT
  ÉCRIRE('Donner un nombre : ');
  LIRE(nombre);
  ÉCRIRE('L\'inverse du nombre : ', nombre, 'est : ', 1/nombre);
FIN.

ALGORITHME valeur_absolue;
VAR Nombre : Entier ;
DÉBUT
  LIRE(nombre) ;
  SI (nombre < 0) ALORS
    nombre <- -(nombre) ;
  FIN SI ;
  ÉCRIRE('La valeur absolue est', nombre) ;
FIN.

ALGORITHME InverseComplet ;
VAR nombre: Réel ;
DÉBUT
  ÉCRIRE('Donner un nombre') ;
  LIRE(nombre) ;
  SI (nombre <> 0) ALORS
    ÉCRIRE('L\'inverse du nombre : ', nombre, ' est : ', 1/nombre) ;
  FIN SI ;
  SI (nombre = 0) ALORS
    ÉCRIRE('le nombre tapé est nul') ;
  FIN SI ;
FIN.

syntax.point:
SI (condition) ALORS
  Traitement 1 ;
SINON
  Traitement 2 ;
FIN SI ;

example.point:
ALGORITHME InverseAltcomp;
VAR nombre : Réel ;
DÉBUT
  LIRE(nombre) ;
  SI (nombre <> 0) ALORS
    ÉCRIRE('L\'inverse du nombre : ', nombre, ' est : ', 1/nombre) ;
  SINON
    ÉCRIRE('le nombre introduit est nul') ;
  FIN SI ;
FIN.

ALGORITHME Observation ;
VAR Moyenne : Réel ;
DÉBUT
  LIRE(Moyenne) ;
  SI (Moyenne >= 10) ALORS
    ÉCRIRE('Admis') ;
  SINON
    SI (Moyenne >= 9.5) ALORS
      ÉCRIRE('Racheté') ;
    SINON
      ÉCRIRE('Ajourné') ;
    FIN SI ;
  FIN SI ;
FIN.

syntax.point:
SELON (expression) FAIRE
  CAS C1 : Traitement 1 ;
  CAS C2 : Traitement 2 ;
  CAS C3 : Traitement 3 ;
  ...
  CAS CN : Traitement N ;
  CAS AUTRE Traitement (N+1) ;
FIN SELON ;

switch (expression) {
  case C1 : Traitement 1 ; break;
  case C2 : Traitement 2 ; break;
  case C3 : Traitement 3 ; break;
  ...
  case CN : Traitement N ; break;
  default : Traitement (N+1) ;
}

example.point:
ALGORITHME jours_mois ;
VAR mois : Entier ;
DÉBUT
  ÉCRIRE('De quel mois s\'agit-il?');
  LIRE(mois) ;
  SELON (mois) FAIRE
    CAS 1, 3, 5, 7, 8, 10, 12 : ÉCRIRE('Nombre de jours : 31') ;
    CAS 4, 6, 9, 11 : ÉCRIRE('Nombre de jours : 30') ;
    CAS 2 : ÉCRIRE('Nombre de jours : 28 ou 29') ;
    CAS AUTRE ÉCRIRE('Ce mois n\'existe pas') ;
  FIN SELON ;
FIN.
